const placeholderMembersByEmail = `-- name: PlaceholderMembersByEmail :many
SELECT m.id AS member_id, u.id AS user_id FROM members m JOIN users u ON u.id = m.user_id
WHERE m.organization_id = $1 AND u.is_placeholder = true AND u.email = $2
`

type PlaceholderMembersByEmailParams struct {
	OrganizationID pgtype.UUID
	Email          string
}

type PlaceholderMembersByEmailRow struct {
	MemberID pgtype.UUID
	UserID   pgtype.UUID
}

func (q *Queries) PlaceholderMembersByEmail(ctx context.Context, arg PlaceholderMembersByEmailParams) ([]PlaceholderMembersByEmailRow, error) {
	rows, err := q.db.Query(ctx, placeholderMembersByEmail, arg.OrganizationID, arg.Email)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PlaceholderMembersByEmailRow
	for rows.Next() {
		var i PlaceholderMembersByEmailRow
		if err := rows.Scan(&i.MemberID, &i.UserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

