const propagateBillableRateForMember = `-- name: PropagateBillableRateForMember :exec

UPDATE time_entries te SET billable_rate = $3, updated_at = now()
WHERE te.billable = true AND te.organization_id = $1 AND te.member_id = $2
  AND NOT EXISTS (
    SELECT 1 FROM projects p
    WHERE p.id = te.project_id
      AND (p.billable_rate IS NOT NULL
        OR EXISTS (SELECT 1 FROM project_members pm
                   WHERE pm.project_id = p.id
                     AND pm.billable_rate IS NOT NULL
                     AND pm.member_id = te.member_id)))
`

type PropagateBillableRateForMemberParams struct {
	OrganizationID pgtype.UUID
	MemberID       pgtype.UUID
	BillableRate   *int32
}

// Billable-rate propagation (BillableRateService) ---------------------------
func (q *Queries) PropagateBillableRateForMember(ctx context.Context, arg PropagateBillableRateForMemberParams) error {
	_, err := q.db.Exec(ctx, propagateBillableRateForMember, arg.OrganizationID, arg.MemberID, arg.BillableRate)
	return err
}

