const updateOrganization = `-- name: UpdateOrganization :one
UPDATE organizations SET name = $2, currency = $3, billable_rate = $4,
    employees_can_see_billable_rates = $5, employees_can_manage_tasks = $6,
    prevent_overlapping_time_entries = $7, breaks_enabled = $8,
    number_format = $9, currency_format = $10, date_format = $11,
    interval_format = $12, time_format = $13, user_id = $14, updated_at = now()
WHERE id = $1
RETURNING id, user_id, name, personal_team, billable_rate, currency, created_at, updated_at, employees_can_see_billable_rates, number_format, currency_format, date_format, interval_format, time_format, prevent_overlapping_time_entries, employees_can_manage_tasks, breaks_enabled
`

type UpdateOrganizationParams struct {
	ID                            pgtype.UUID
	Name                          string
	Currency                      string
	BillableRate                  *int32
	EmployeesCanSeeBillableRates  bool
	EmployeesCanManageTasks       bool
	PreventOverlappingTimeEntries bool
	BreaksEnabled                 bool
	NumberFormat                  string
	CurrencyFormat                string
	DateFormat                    string
	IntervalFormat                string
	TimeFormat                    string
	UserID                        pgtype.UUID
}

func (q *Queries) UpdateOrganization(ctx context.Context, arg UpdateOrganizationParams) (Organization, error) {
	row := q.db.QueryRow(ctx, updateOrganization,
		arg.ID,
		arg.Name,
		arg.Currency,
		arg.BillableRate,
		arg.EmployeesCanSeeBillableRates,
		arg.EmployeesCanManageTasks,
		arg.PreventOverlappingTimeEntries,
		arg.BreaksEnabled,
		arg.NumberFormat,
		arg.CurrencyFormat,
		arg.DateFormat,
		arg.IntervalFormat,
		arg.TimeFormat,
		arg.UserID,
	)
	var i Organization
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Name,
		&i.PersonalTeam,
		&i.BillableRate,
		&i.Currency,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.EmployeesCanSeeBillableRates,
		&i.NumberFormat,
		&i.CurrencyFormat,
		&i.DateFormat,
		&i.IntervalFormat,
		&i.TimeFormat,
		&i.PreventOverlappingTimeEntries,
		&i.EmployeesCanManageTasks,
		&i.BreaksEnabled,
	)
	return i, err
}
